152	public:
153	  static PrimFunc Apply(PrimFunc func, const LoadStore2StateMap &states) {
154	    arith::Analyzer analyzer;
155	    NegativeIndexRewriter rewriter(&analyzer, states);
156	    PrimFuncNode *func_node = func.CopyOnWrite();
157	    func_node->body = rewriter.VisitStmt(func_node->body);
