163	                        const LoadStore2StateMap &states)
164	      : arith::IRMutatorWithAnalyzer(analyzer), states_(states) {}
165	
166	  ffi::Array<PrimExpr> UpdateIdx(const ffi::Array<PrimExpr> &indices,
167	                                 const ffi::Array<PrimExpr> &buffer_shape,
168	                                 const std::vector<IndexSignState> &state_vec) {
169	    ICHECK_EQ(state_vec.size(), indices.size())
170	        << "State vector size mismatch for buffer load/store indices ("
171	        << indices << ")";
172	    ffi::Array<PrimExpr> new_indices = indices;
173	    for (size_t i = 0; i < indices.size(); ++i) {
174	      if (state_vec[i] != IndexSignState::kNegative)
175	        continue;
176	      new_indices.Set(i, analyzer_->Simplify(buffer_shape[i] + indices[i]));
177	    }
178	    return new_indices;
179	  }
180	
181	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
182	    BufferLoad load =
183	        Downcast<BufferLoad>(arith::IRMutatorWithAnalyzer::VisitExpr_(op));
184	
185	    auto it = states_.find(op);
186	    if (it == states_.end())
187	      return load;
188	
189	    auto indices = UpdateIdx(load->indices, load->buffer->shape, it->second);
190	    return BufferLoad(load->buffer, indices, load->predicate);
191	  }
192	
193	  Stmt VisitStmt_(const BufferStoreNode *op) final {
194	    BufferStore store =
195	        Downcast<BufferStore>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
196	
197	    auto it = states_.find(op);
198	    if (it == states_.end())
199	      return store;
200	
201	    auto indices = UpdateIdx(store->indices, store->buffer->shape, it->second);
202	    return BufferStore(store->buffer, store->value, indices, store->predicate);
203	  }
204	
205	private:
206	  const LoadStore2StateMap &states_;
207	};
