28	namespace tvm {
29	namespace tl {
30	
31	using namespace tir;
32	
33	static Buffer makeBufferWithLayout(const Buffer &buffer, const Layout &layout,
34	                                   Map<Var, Var> &var_remap) {
35	  const auto *ptr_type =
36	      TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
37	  Type new_type;
38	  // convert fragments to normal local buffer
39	  if (ptr_type->storage_scope == "local.fragment") {
40	    new_type = PointerType(ptr_type->element_type, "local");
41	  } else {
42	    new_type = buffer->data->type_annotation;
43	  }
44	  Var new_var;
45	  if (ptr_type->storage_scope == "global") {
46	    new_var = buffer->data;
47	  } else {
48	    if (var_remap.count(buffer->data)) {
49	      new_var = var_remap[buffer->data];
50	    } else {
51	      new_var = Var(buffer->data->name_hint, new_type);
52	      var_remap.Set(buffer->data, new_var);
53	    }
54	  }
55	  Array<PrimExpr> layout_shape = layout->OutputShape();
56	  Array<PrimExpr> output_shape = layout_shape;
57	
58	  if (ptr_type->storage_scope == "shared" ||
59	      ptr_type->storage_scope == "shared.dyn") {
60	    int replicate_extent = 1;
61	    Array<PrimExpr> buffer_shape = buffer->shape;
62	    int buffer_extent = 1;
63	    int layout_extent = 1;
64	    for (size_t i = 0; i < buffer_shape.size(); i++) {
65	      auto shape = buffer_shape[i].as<IntImmNode>();
66	      buffer_extent *= shape->value;
67	    }
68	    for (size_t i = 0; i < layout_shape.size(); i++) {
69	      auto shape = layout_shape[i].as<IntImmNode>();
70	      layout_extent *= shape->value;
71	    }
72	    replicate_extent = buffer_extent / layout_extent;
73	    if (replicate_extent > 1) {
74	      output_shape.insert(output_shape.begin(), replicate_extent);
75	    }
76	  }
77	  return Buffer(new_var, buffer->dtype, output_shape, {}, buffer->elem_offset,
78	                buffer->name, buffer->data_alignment, buffer->offset_factor,
79	                buffer->buffer_type);
80	}
81	
82	// The function `makeBufferWithLayout` creates a new Buffer object based on the
83	// given buffer and layout. It handles remapping of buffer variables, adjusts
84	// the storage scope if needed (e.g., from "local.fragment" to "local"), and
85	// computes the output shape according to the layout. For shared memory buffers,
86	// it also handles replication if the buffer's extent is larger than the
87	// layout's extent.
88	class LayoutRemapRewriter : public arith::IRMutatorWithAnalyzer {
89	public:
90	  static Stmt Substitute(Stmt stmt, Map<Buffer, Layout> layout_remap) {
91	    arith::Analyzer analyzer;
92	    LayoutRemapRewriter substituter(&analyzer);
93	    substituter.layout_remap_ = std::move(layout_remap);
94	    return substituter.VisitStmt(stmt);
95	  }
96	
97	private:
98	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
99	
100	  Stmt VisitStmt_(const BlockNode *op) final {
101	    auto block = Downcast<Block>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
102	    if (op->annotations.count(attr::kLayoutMap)) {
103	      block.CopyOnWrite()->annotations.Set(attr::kLayoutMap, layout_remap_);
104	    }
105	    return block;
106	  }
107	
108	  Map<Buffer, Layout> layout_remap_;
109	};
110	
111	/*!
112	 * \brief A class that rewrites buffer references in a statement based on a
113	 * given buffer remapping.
114	 *
115	 * This class is used to update buffer references in a statement after buffer
116	 * transformations have been applied. It specifically handles the remapping of
117	 * padding annotations.
118	 */
119	class RemapBufferRewriter : public arith::IRMutatorWithAnalyzer {
120	public:
121	  /*!
122	   * \brief Substitute buffer references in a statement based on a given buffer
123	   * remapping. \param stmt The statement to rewrite. \param buffer_remap A map
124	   * from old buffers to new buffers. \return The rewritten statement.
125	   */
126	  static Stmt Substitute(const Stmt &stmt, Map<Buffer, Buffer> buffer_remap) {
127	    arith::Analyzer analyzer;
128	    RemapBufferRewriter substituter(&analyzer);
129	    substituter.buffer_remap_ = std::move(buffer_remap);
130	    return substituter.VisitStmt(stmt);
131	  }
132	
133	private:
134	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
135	
136	  Stmt VisitStmt_(const BlockNode *op) final {
137	    if (op->annotations.count(attr::kSafeValueMap)) {
138	      return RewritePaddingMap(op);
139	    }
140	    return IRMutatorWithAnalyzer::VisitStmt_(op);
141	  }
142	
143	  /*!
144	   * \brief Rewrite the padding map annotation of a block.
145	   * \param op The block node to rewrite.
146	   * \return The rewritten block.
147	   */
148	  Stmt RewritePaddingMap(const BlockNode *op) {
149	    auto safe_value_map = op->annotations.Get(attr::kSafeValueMap);
150	    if (!safe_value_map) {
151	      LOG(FATAL) << "Padding map annotation is missing";
152	    }
153	
154	    Map<Var, Var> var_remap = CreateVarRemap();
155	    Map<Var, PrimExpr> new_safe_value_map = RemapPaddingMap(
156	        Downcast<Map<Var, PrimExpr>>(safe_value_map.value()), var_remap);
157	
158	    auto block = Downcast<Block>(IRMutatorWithAnalyzer::VisitStmt_(op));
159	    auto block_ptr = block.CopyOnWrite();
160	    block_ptr->annotations.Set(attr::kSafeValueMap, new_safe_value_map);
161	    return block;
162	  }
163	
164	  /*!
165	   * \brief Create a mapping from old variables to new variables based on buffer
166	   * remapping. \return A map from old variables to new variables.
167	   */
168	  Map<Var, Var> CreateVarRemap() const {
169	    Map<Var, Var> var_remap;
170	    for (const auto &[buffer, buffer_remap] : buffer_remap_) {
171	      var_remap.Set(buffer->data, buffer_remap->data);
172	    }
173	    return var_remap;
174	  }
175	
176	  /*!
177	   * \brief Remap the padding map using the variable remapping.
178	   * \param safe_value_map The original padding map.
179	   * \param var_remap The variable remapping.
180	   * \return The remapped padding map.
181	   */
182	  Map<Var, PrimExpr> RemapPaddingMap(const Map<Var, PrimExpr> &safe_value_map,
183	                                     const Map<Var, Var> &var_remap) const {
184	    Map<Var, PrimExpr> new_safe_value_map;
185	    for (const auto &[var, padding] : safe_value_map) {
186	      if (var_remap.count(var)) {
187	        new_safe_value_map.Set(var_remap.at(var), padding);
188	      } else {
189	        new_safe_value_map.Set(var, padding);
190	      }
191	    }
192	    return new_safe_value_map;
193	  }
194	
195	  Map<Buffer, Buffer> buffer_remap_;
196	};
