198	class LowerTileOpPass : arith::IRMutatorWithAnalyzer {
199	public:
200	  static PrimFunc Substitute(PrimFunc f) {
201	    arith::Analyzer analyzer;
202	    LowerTileOpPass substituter(&analyzer);
203	    // Trace the buffer map for tvm_access_ptr
204	    substituter.buffer_map_.insert(f->buffer_map.begin(), f->buffer_map.end());
205	    for (const auto &[_, buffer] : f->buffer_map) {
206	      substituter.buffer_data_to_buffer_.Set(buffer->data, buffer);
207	    }
208	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
209	    ICHECK(target.defined()) << "LowerTileOpPass: Require the target attribute";
210	    substituter.target_ = target.value();
211	    PrimFuncNode *fptr = f.CopyOnWrite();
212	    fptr->body = substituter.VisitStmt(f->body);
213	    fptr->body =
214	        RemapBufferRewriter::Substitute(fptr->body, substituter.buffer_remap_);
215	    fptr->body =
216	        LayoutRemapRewriter::Substitute(fptr->body, substituter.layout_remap_);
217	    tvm::transform::PassContext ctxt = tvm::transform::PassContext::Current();
218	    Optional<Bool> opt_disable_tma_lower =
219	        ctxt->GetConfig(kDisableTMALower, Optional<Bool>());
220	
221	    if (!opt_disable_tma_lower.value_or(Bool(false))) {
222	      // @lei: this is a workaround, as if we don't disable tma lower,
223	      // cp async lowering won't be generated.
224	      ctxt->config.Set(kDisableTMALower, Bool(!substituter.has_tma_));
225	    }
226	    return f;
227	  }
