229	private:
230	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
231	
232	  Stmt VisitStmt_(const BlockNode *op) final {
233	    // Record the mapping from buffer data var to buffer for later lookup
234	    for (auto buffer : op->alloc_buffers) {
235	      buffer_map_.insert({buffer->data, buffer});
236	    }
237	    for (auto match_buffer : op->match_buffers) {
238	      buffer_map_.insert({match_buffer->buffer->data, match_buffer->buffer});
239	    }
240	    for (auto buffer : op->alloc_buffers) {
241	      buffer_data_to_buffer_.Set(buffer->data, buffer);
242	    }
243	    Map<Var, Layout> vmap;
244	    if (op->annotations.count(attr::kLayoutMap)) {
245	      auto layout_map = op->annotations.at(attr::kLayoutMap)
246	                            .as<Map<Buffer, Layout>>()
247	                            .value();
248	      for (auto [buffer, layout] : layout_map) {
249	        buffer_remap_.Set(buffer,
250	                          makeBufferWithLayout(buffer, layout, var_remap_));
251	        layout_map_.Set(buffer, layout);
252	      }
253	    }
254	    // Begin a new workspace collection frame for this block scope
255	    workspace_stack_.emplace_back();
256	
257	    auto block = Downcast<Block>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
258	    auto block_ptr = block.CopyOnWrite();
259	    for (size_t i = 0; i < block->alloc_buffers.size(); i++) {
260	      auto buffer = block->alloc_buffers[i];
261	      if (buffer_remap_.count(buffer)) {
262	        block_ptr->alloc_buffers.Set(i, buffer_remap_[buffer]);
263	      }
264	    }
265	    // Attach any workspaces requested within this block to its alloc_buffers
266	    if (!workspace_stack_.empty()) {
267	      for (const auto &buffer : workspace_stack_.back()) {
268	        block_ptr->alloc_buffers.push_back(buffer);
269	      }
270	      workspace_stack_.pop_back();
271	    }
272	    return block;
273	  }
274	
275	  int CheckAndGetBufferRowSize(const Buffer &buffer) {
276	    CHECK(buffer->shape.size() >= 2)
277	        << "The dimension of Buffer \"" << buffer->name << "\" with shape "
278	        << buffer->shape << " should be at least 2";
279	
280	    auto dim = buffer->shape.size();
281	    auto buffer_row_size = buffer->shape[dim - 1].as<IntImmNode>()->value;
282	    return buffer_row_size;
283	  }
284	
285	  struct AccessPtrResult {
286	    PrimExpr expr;
287	    bool rewritten{false};
288	  };
289	
290	  AccessPtrResult
291	  HandleAccessPtrAndOffset(const PrimExpr &access_ptr,
292	                           const Optional<PrimExpr> &offset = std::nullopt,
293	                           DataType dtype = DataType::Int(32)) {
294	    AccessPtrResult result{access_ptr, false};
295	    // The 2th arg of T.tvm_access_ptr call is offset, we set it to 0 and
296	    // accumulate it to smem_offset
297	    CHECK(access_ptr->IsInstance<CallNode>())
298	        << "Invalid access ptr for permuted layout: " << access_ptr;
299	    auto access_ptr_call = Downcast<Call>(access_ptr);
300	    if (access_ptr_call->op.same_as(builtin::tvm_access_ptr())) {
301	      LOG(FATAL) << "Transformation for tvm_access_ptr is not implemented yet";
302	    } else if (access_ptr_call->op.same_as(builtin::address_of())) {
303	      Optional<PrimExpr> resolved = ResolveBufferLoad(access_ptr_call->args[0]);
304	      ICHECK(resolved.defined())
305	          << "Invalid access op for permuted layout: " << access_ptr;
306	      PrimExpr load_expr = resolved.value();
307	      if (!load_expr.same_as(access_ptr_call->args[0])) {
308	        auto node = access_ptr_call.CopyOnWrite();
309	        node->args.Set(0, load_expr);
310	        access_ptr_call =
311	            Call(access_ptr_call->dtype, access_ptr_call->op, {load_expr},
312	                 access_ptr_call->annotations, access_ptr_call->span);
313	      }
314	      BufferLoad load = Downcast<BufferLoad>(access_ptr_call->args[0]);
315	      Array<PrimExpr> indices = load->indices;
316	      Array<PrimExpr> old_shape = load->buffer->shape;
317	
318	      CHECK_EQ(indices.size(), old_shape.size())
319	          << "Indices size and shape size must match for general N-dimensional "
320	             "buffer "
321	          << "but got indices size: " << indices.size()
322	          << " and shape size: " << old_shape.size();
323	
324	      PrimExpr elem_offset = 0;
325	      PrimExpr stride = 1;
326	
327	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
328	        elem_offset += indices[i] * stride;
329	        stride *= old_shape[i];
330	      }
331	
332	      PrimExpr smem_offset =
333	          elem_offset + (offset.defined() ? offset.value() : 0);
334	
335	      Buffer remap_key = FindRemapBuffer(load->buffer).value_or(load->buffer);
336	      Optional<Layout> layout = FindLayout(remap_key);
337	      if (!layout.defined() || !buffer_map_.count(remap_key->data)) {
338	        return result;
339	      }
340	      auto new_buffer = buffer_remap_.count(remap_key)
341	                            ? buffer_remap_[remap_key]
342	                            : load->buffer;
343	      auto new_shape = new_buffer->shape;
344	
345	      auto buffer_map_iter = buffer_map_.find(Downcast<Var>(remap_key->data));
346	
347	      int buffer_row_size = CheckAndGetBufferRowSize(buffer_map_iter->second);
348	      (void)buffer_row_size;
349	
350	      // Convert offset to target-dimension, reindex it and convert it back
351	      Array<PrimExpr> multi_dim_indices;
352	      PrimExpr remaining_offset = smem_offset;
353	
354	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
355	        multi_dim_indices.insert(multi_dim_indices.begin(),
356	                                 floormod(remaining_offset, old_shape[i]));
357	        remaining_offset = floordiv(remaining_offset, old_shape[i]);
358	      }
359	
360	      auto forward_indices = layout.value()->Forward(multi_dim_indices);
361	      PrimExpr new_offset = 0;
362	      PrimExpr stride_offset = 1;
363	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
364	        new_offset += forward_indices[i] * stride_offset;
365	        stride_offset *= new_shape[i];
366	      }
367	      new_offset = analyzer_->Simplify(new_offset);
368	
369	      Array<PrimExpr> new_indices;
370	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
371	        new_indices.insert(new_indices.begin(),
372	                           floormod(new_offset, new_shape[i]));
373	        new_offset = floordiv(new_offset, new_shape[i]);
374	      }
375	
376	      Array<PrimExpr> new_args = {BufferLoad(new_buffer, new_indices)};
377	      if (buffer_remap_.count(remap_key)) {
378	        layout_remap_.Set(new_buffer, layout.value());
379	      }
380	      result.rewritten = true;
381	      result.expr = Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
382	                         access_ptr_call->annotations, access_ptr_call->span);
383	      return result;
384	    } else {
385	      LOG(FATAL) << "Invalid access op for permuted layout: " << access_ptr;
386	    }
387	
388	    return result;
389	  }
390	
391	  Optional<PrimExpr> ResolveBufferLoad(const PrimExpr &expr) const {
392	    if (expr->IsInstance<BufferLoadNode>()) {
393	      return expr;
394	    }
395	    if (const auto *var_node = expr.as<VarNode>()) {
396	      Var var = tvm::ffi::GetRef<Var>(var_node);
397	      auto it = let_bindings_.find(var);
398	      if (it != let_bindings_.end()) {
399	        return it->second;
400	      }
401	    }
402	    return Optional<PrimExpr>();
403	  }
404	
405	  Optional<Buffer> FindRemapBuffer(const Buffer &buffer) const {
406	    if (buffer_remap_.count(buffer)) {
407	      return buffer;
408	    }
409	    auto it = buffer_map_.find(buffer->data);
410	    if (it != buffer_map_.end() && buffer_remap_.count(it->second)) {
411	      return it->second;
412	    }
413	    for (const auto &kv : buffer_remap_) {
414	      if (kv.first->data.same_as(buffer->data)) {
415	        return kv.first;
416	      }
417	      if (kv.first->name == buffer->name) {
418	        return kv.first;
419	      }
420	    }
421	    return Optional<Buffer>();
422	  }
423	
424	  Optional<Layout> FindLayout(const Buffer &buffer) const {
425	    if (layout_map_.count(buffer)) {
426	      return layout_map_[buffer];
427	    }
428	    auto it = buffer_map_.find(buffer->data);
429	    if (it != buffer_map_.end() && layout_map_.count(it->second)) {
430	      return layout_map_[it->second];
431	    }
432	    for (const auto &kv : layout_map_) {
433	      if (kv.first->data.same_as(buffer->data)) {
434	        return kv.second;
435	      }
436	      if (kv.first->name == buffer->name) {
437	        return kv.second;
438	      }
439	    }
440	    return Optional<Layout>();
441	  }
442	
443	  PrimExpr VisitExpr_(const tir::CallNode *op) final {
444	    if ((!has_tma_) && (op->op.same_as(tl::tma_load()) ||
445	                        op->op.same_as(tl::tma_load_im2col()) ||
446	                        op->op.same_as(tl::tma_store()))) {
447	      has_tma_ = true;
448	    }
449	    Array<RelaxExpr> ptx_instructions = {builtin::ptx_ldmatrix(),
450	                                         builtin::mma_store()};
451	
452	    if (std::find(ptx_instructions.begin(), ptx_instructions.end(), op->op) ==
453	        ptx_instructions.end()) {
454	      auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
455	      return call;
456	    } else {
457	      is_ptx_ = true;
458	    }
459	    // Rewrite from/to shared or shared.dyn to/from local
460	    auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
461	    if (call->op.same_as(builtin::ptx_ldmatrix())) {
462	      // form: T.ptx_ldmatrix(..., smem_ptr, smem_offset)
463	      // smem_ptr: T.tvm_access_ptr(ptype, data, offset, extent, rw_mask)
464	      // or T.address_of(buffer, offset)
465	      PrimExpr access_ptr = call->args[5];
466	      PrimExpr smem_offset = call->args[6];
467	      Call address_of_call = Downcast<Call>(access_ptr);
468	      if (!address_of_call->op.same_as(builtin::address_of())) {
469	        LOG(FATAL) << "Invalid access ptr for permuted layout: " << access_ptr;
470	      }
471	      Optional<PrimExpr> resolved = ResolveBufferLoad(address_of_call->args[0]);
472	      ICHECK(resolved.defined())
473	          << "Invalid address_of argument for permuted layout: "
474	          << address_of_call->args[0];
475	      PrimExpr load_expr = resolved.value();
476	      if (!load_expr.same_as(address_of_call->args[0])) {
477	        auto call_node = call.CopyOnWrite();
478	        call_node->args.Set(5, Call(address_of_call->dtype, address_of_call->op,
479	                                    {load_expr}, address_of_call->annotations,
480	                                    address_of_call->span));
481	        address_of_call = Downcast<Call>(call->args[5]);
482	        access_ptr = call->args[5];
483	      }
484	      BufferLoad load = Downcast<BufferLoad>(address_of_call->args[0]);
485	      auto new_access_ptr =
486	          HandleAccessPtrAndOffset(access_ptr, smem_offset, call->dtype);
487	      if (new_access_ptr.rewritten) {
488	        auto new_call = call.CopyOnWrite();
489	        new_call->args.Set(5, new_access_ptr.expr);
490	        new_call->args.Set(6, IntImm(smem_offset->dtype, 0));
491	      }
492	    } else if (call->op.same_as(builtin::mma_store())) {
493	      // because we will directly store result to Buffer instead of calling
494	      // mma_store now
495	      auto access_ptr = call->args[2];
496	      auto new_access_ptr =
497	          HandleAccessPtrAndOffset(access_ptr, std::nullopt, call->dtype);
498	      if (new_access_ptr.rewritten) {
499	        auto new_call = call.CopyOnWrite();
500	        new_call->args.Set(2, new_access_ptr.expr);
501	      }
502	    } else {
503	      LOG(FATAL) << "Invalid call node: " << call;
504	    }
505	    is_ptx_ = false;
506	    return call;
507	  }
508	
509	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
510	    auto load = Downcast<BufferLoad>(IRMutatorWithAnalyzer::VisitExpr_(op));
511	    if (is_ptx_) {
512	      return load;
513	    }
514	    auto buffer = load->buffer;
515	    if (buffer_remap_.count(buffer)) {
516	      auto new_indices = layout_map_[buffer]->Forward(load->indices);
517	      auto new_buffer = buffer_remap_[load->buffer];
518	      layout_remap_.Set(new_buffer, layout_map_[load->buffer]);
519	      return BufferLoad(new_buffer, new_indices);
520	    } else if (var_remap_.count(buffer->data)) {
521	      auto new_buffer = Buffer(
522	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
523	          buffer->strides, buffer->elem_offset, buffer->name,
524	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
525	      return BufferLoad(new_buffer, load->indices);
526	    }
527	    return load;
528	  }
529	
530	  Stmt VisitStmt_(const BufferStoreNode *op) final {
531	    auto store = Downcast<BufferStore>(IRMutatorWithAnalyzer::VisitStmt_(op));
532	    auto buffer = store->buffer;
533	    if (buffer_remap_.count(buffer)) {
534	      auto new_indices = layout_map_[buffer]->Forward(store->indices);
535	      auto new_buffer = buffer_remap_[store->buffer];
536	      layout_remap_.Set(new_buffer, layout_map_[store->buffer]);
537	      return BufferStore(new_buffer, store->value, new_indices);
538	    } else if (var_remap_.count(buffer->data)) {
539	      auto new_buffer = Buffer(
540	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
541	          buffer->strides, buffer->elem_offset, buffer->name,
542	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
543	      return BufferStore(new_buffer, store->value, store->indices);
544	    }
545	    return store;
546	  }
547	
548	  PrimExpr VisitExpr_(const VarNode *op) final {
549	    auto var = Downcast<Var>(IRMutatorWithAnalyzer::VisitExpr_(op));
550	    if (buffer_data_to_buffer_.count(var)) {
551	      auto buffer = buffer_data_to_buffer_[var];
552	      if (buffer_remap_.count(buffer))
553	        return buffer_remap_[buffer]->data;
554	    }
555	    return var;
556	  }
557	
558	  Stmt VisitStmt_(const LetStmtNode *op) final {
559	    PrimExpr value = this->VisitExpr(op->value);
560	    bool recorded = false;
561	    if (value->IsInstance<BufferLoadNode>()) {
562	      let_bindings_[op->var] = value;
563	      recorded = true;
564	    }
565	    if (SideEffect(value) <= CallEffectKind::kPure) {
566	      analyzer_->Bind(op->var, value);
567	    }
568	    Stmt body = this->VisitStmt(op->body);
569	    if (recorded) {
570	      let_bindings_.erase(op->var);
571	    }
572	    if (value.same_as(op->value) && body.same_as(op->body)) {
573	      return tvm::ffi::GetRef<Stmt>(op);
574	    } else {
575	      auto n = this->CopyOnWrite(op);
576	      n->value = value;
577	      n->body = body;
578	      return Stmt(n);
579	    }
580	  }
