74	  void RunInferStep(int cur_infer_id, InferLevel level, bool update_queue,
75	                    LayoutMap &layout_map, const LayoutMap &strict_layout_map,
76	                    std::deque<int> &q, std::vector<bool> &in_queue) {
77	    auto num_infer = infer_list_.size();
78	
79	    // Range check for cur_infer_id
80	    ICHECK_GE(cur_infer_id, 0) << "cur_infer_id is negative, which is invalid.";
81	    ICHECK_LT(cur_infer_id, num_infer)
82	        << "cur_infer_id " << cur_infer_id << " is out of range, must be < "
83	        << num_infer << ".";
84	
85	    // Make sure we can safely access infer_list_[cur_infer_id] and
86	    // thread_var_vec_[cur_infer_id]
87	    auto &next = infer_list_[cur_infer_id];
88	    auto iter_var = thread_var_vec_[cur_infer_id];
89	    auto thread_bounds = thread_bounds_vec_[cur_infer_id];
90	    arith::Analyzer *cur_analyzer = analyzer_vec_[cur_infer_id].get();
91	    auto buffer_oob = buffer_oob_vec_[cur_infer_id];
92	    // Double-check that 'next' is valid
93	    ICHECK(next.defined()) << "infer_list_[" << cur_infer_id
94	                           << "] is null inside run_infer_step.";
95	
96	    // Check iter_var->dom and dom->extent
97	    ICHECK(iter_var.defined())
98	        << "thread_var_vec_[" << cur_infer_id << "] is not defined.";
99	    ICHECK(iter_var->dom.defined())
100	        << "iter_var->dom is not defined for infer_list_[" << cur_infer_id
101	        << "].";
102	    ICHECK(iter_var->dom->extent.defined())
103	        << "iter_var->dom->extent is not defined for infer_list_["
104	        << cur_infer_id << "].";
105	
106	    const int64_t *extent_ptr = as_const_int(iter_var->dom->extent);
107	    ICHECK(extent_ptr != nullptr)
108	        << "iter_var->dom->extent is not a constant integer, which is "
109	           "required for layout inference.";
110	
111	    // Run InferLayout
112	    auto updates = next->InferLayout(LayoutInferArgs{target_,
113	                                                     thread_bounds,
114	                                                     layout_map,
115	                                                     cur_analyzer,
116	                                                     buffer_oob,
117	                                                     {},
118	                                                     let_var_to_expr_},
119	                                     level);
120	
121	    // Process the returned updates
122	    for (const auto &[buffer, layout] : updates) {
123	      // Basic validity checks
124	      ICHECK(buffer.defined()) << "InferLayout returned an undefined buffer.";
125	      ICHECK(layout.defined()) << "InferLayout returned an undefined layout.";
126	
127	      // Helper: propagate inferred layout to alias buffers (same data Var)
128	      auto propagate_alias = [&](const Buffer &src_buffer,
129	                                 const Layout &src_layout) {
130	        if (!buffer_data_to_buffers_.count(src_buffer->data))
131	          return;
132	        const auto &siblings = buffer_data_to_buffers_[src_buffer->data];
133	        for (const auto &sib : siblings) {
134	          if (sib.same_as(src_buffer))
135	            continue;
136	          bool shapes_equal =
137	              src_layout->InputShape().size() == sib->shape.size();
138	          if (shapes_equal) {
139	            for (size_t i = 0; i < src_layout->InputShape().size(); ++i) {
140	              if (!analyzer_.CanProveEqual(src_layout->InputShape()[i],
141	                                           sib->shape[i])) {
142	                shapes_equal = false;
143	                break;
144	              }
145	            }
146	          }
147	          Layout target_layout =
148	              shapes_equal
149	                  ? src_layout
150	                  : src_layout->Reshape(sib->shape, &analyzer_,
151	                                        Integer(src_buffer->dtype.bytes()),
152	                                        Integer(sib->dtype.bytes()));
153	          if (layout_map.count(sib)) {
154	            ICHECK(target_layout->IsEqual(layout_map[sib].get()))
155	                << "Get different layout for alias buffer " << sib
156	                << " (data-shared with " << src_buffer
157	                << ")\n current: " << target_layout->DebugOutput()
158	                << "\n previous: " << layout_map[sib]->DebugOutput();
159	          } else {
160	            layout_map.Set(sib, target_layout);
161	            if (update_queue && use_list_.count(sib)) {
162	              for (int idx : use_list_[sib]) {
163	                EnqueueWithPriority(idx, q, in_queue, cur_infer_id, layout_map);
164	              }
165	            }
166	          }
167	        }
168	      };
169	
170	      if (layout_map.count(buffer)) {
171	        // If new layout contains the old one, update map
172	        if (IsFragmentBuffer(buffer) && level != InferLevel::kStrict &&
173	            !strict_layout_map.count(buffer)) {
174	          // Actually this test has been done in ParallelOp::InferLayout
175	          // already. Just do it again to avoid missing implementations in other
176	          // `TileOperator`s.
177	
178	          auto dst_layout_opt = layout.as<Fragment>();
179	          ICHECK(dst_layout_opt.has_value())
180	              << "Failed to cast layout to Fragment for buffer " << buffer
181	              << ", layout type is " << layout->GetTypeKey();
182	          const auto &dst_layout = dst_layout_opt.value();
183	          auto src_layout_opt = layout_map[buffer].as<Fragment>();
184	          ICHECK(src_layout_opt.has_value())
185	              << "Failed to cast layout_map[buffer] to Fragment for buffer "
186	              << buffer << ", layout type is "
187	              << layout_map[buffer]->GetTypeKey();
188	          const auto &src_layout = src_layout_opt.value();
189	          ICHECK(dst_layout->InputDim() == src_layout->InputDim());
190	          Array<PrimExpr> indices;
191	          indices.reserve(dst_layout->InputDim());
192	          arith::Analyzer inner_analyzer;
193	          for (int i = 0; i < dst_layout->InputDim(); ++i) {
194	            auto x = InputPlaceholder(i);
195	            indices.push_back(x);
196	            // should be literal - literal = 0, any analyzer will work
197	            ICHECK(is_zero(inner_analyzer.Simplify(
198	                dst_layout->InputShape()[i] - src_layout->InputShape()[i])));
199	            inner_analyzer.Bind(x, Range(0, dst_layout->InputShape()[i]));
200	          }
201	          if (ProveFragmentContains(src_layout, dst_layout, indices, indices,
202	                                    inner_analyzer)) {
203	            layout_map.Set(buffer, layout);
204	            // Propagate to alias buffers as well
205	            propagate_alias(buffer, layout);
206	            continue;
207	          }
208	        }
209	        // If already in map, ensure they are structurally equal
210	        ICHECK(layout->IsEqual(layout_map[buffer].get()))
211	            << "Get different layout for " << buffer
212	            << "\n current layout: " << layout->DebugOutput()
213	            << "\n previous layout: " << layout_map[buffer]->DebugOutput();
214	        // Ensure aliases are consistent too
215	        propagate_alias(buffer, layout);
216	      } else {
217	        // Otherwise, update map
218	        layout_map.Set(buffer, layout);
219	        // Propagate to alias buffers (may enqueue their users)
220	        propagate_alias(buffer, layout);
221	        if (!update_queue)
222	          continue;
223	
224	        // Check if buffer exists in use_list_
225	        if (!use_list_.count(buffer)) {
226	          LOG(WARNING) << "Layout inference failed for buffer " << buffer
227	                       << ". "
228	                       << "The buffer cannot be inferred with current layout "
229	                          "inference rules.";
230	          continue;
231	        }
232	
233	        // Push back into BFS queue
234	        for (int idx : use_list_[buffer]) {
235	          ICHECK_GE(idx, 0)
236	              << "Index in use_list_ for buffer " << buffer << " is negative.";
237	          ICHECK_LT(idx, num_infer)
238	              << "Index in use_list_ for buffer " << buffer
239	              << " out of range: " << idx << " >= " << num_infer << ".";
240	
241	          EnqueueWithPriority(idx, q, in_queue, cur_infer_id, layout_map);
242	        }
243	      }
244	    }
245	  };
246	
247	  void FinishInferQueue(InferLevel level, LayoutMap &layout_map,
248	                        const LayoutMap &strict_layout_map, std::deque<int> &q,
249	                        std::vector<bool> &in_queue) {
250	    auto num_infer = infer_list_.size();
251	
252	    while (!q.empty()) {
253	      int cur_infer_id = q.front();
254	      q.pop_front();
255	      // Range check again, just to be safe
256	      ICHECK_GE(cur_infer_id, 0);
257	      ICHECK_LT(cur_infer_id, num_infer);
258	
259	      in_queue[cur_infer_id] = false;
260	      RunInferStep(cur_infer_id, level, true, layout_map, strict_layout_map, q,
261	                   in_queue);
262	    }
263	  };
264	
265	  LayoutInferenceResult Run() {
266	    // Basic consistency check: infer_list_ and thread_var_vec_ should have the
267	    // same size
268	    ICHECK_EQ(infer_list_.size(), thread_var_vec_.size())
269	        << "Size mismatch: infer_list_ and thread_var_vec_ must match in "
270	           "length.";
271	    ICHECK_EQ(thread_bounds_vec_.size(), infer_list_.size())
272	        << "Size mismatch: thread_bounds_vec_ and infer_list_ must match in "
273	           "length.";
274	    ICHECK_EQ(analyzer_vec_.size(), infer_list_.size())
275	        << "Size mismatch: analyzer_vec_ and infer_list_ must match in "
276	           "length.";
277	    ICHECK_EQ(buffer_oob_vec_.size(), infer_list_.size())
278	        << "Size mismatch: buffer_oob_vec_ and infer_list_ must match in "
279	           "length.";
280	
281	    DLOG(INFO) << "[InferLayout] all participating operators:" << '\n';
282	    for (int i = 0; i < infer_list_stmt_.size(); ++i) {
283	      DLOG(INFO) << "    op " << i << ":" << infer_list_stmt_[i] << '\n';
284	    }
285	
286	    // If needed, you can also check that annotated_layout_map_ is not empty, or
287	    // anything else relevant to your setup.
288	
289	    // Copy the annotated layout map to local variable
290	    Map<Buffer, Layout> layout_map = annotated_layout_map_;
291	    Map<Buffer, Layout> strict_layout_map;
292	    int num_infer = infer_list_.size();
293	
294	    // Prepare BFS queue for iterative inference
295	    std::deque<int> q;
296	    std::vector<bool> in_queue(num_infer, true);
297	    for (int i = 0; i < num_infer; i++) {
298	      // Check that each infer_list_ entry is valid
299	      ICHECK(infer_list_[i].defined())
300	          << "infer_list_[" << i
301	          << "] is null. The inference object is not allocated properly.";
302	
303	      // Check that each thread_var_vec_ entry is defined
304	      if (!thread_var_vec_[i].defined() && skip_thread_partition_) {
305	        thread_var_vec_[i] = thread_var_;
306	      }
307	      q.push_back(i);
308	    }
309	
310	    // step 0: set fully replicated layout for floating fragment buffers
311	    // Floating buffers are accessed outside TileOps (e.g., in if conditions),
312	    // so they must be replicated across all threads.
313	    for (const auto &[buffer, thread_bounds] : floating_fragment_buffers_) {
314	      if (layout_map.count(buffer))
315	        continue;
316	      auto frag =
317	          Fragment::FullyReplicated(buffer->shape, thread_bounds->extent);
318	      layout_map.Set(buffer, frag);
319	    }
320	
321	    // step 1: infer strict layout
322	    for (int i = 0; i < num_infer; i++) {
323	      RunInferStep(i, InferLevel::kStrict, false, layout_map, strict_layout_map,
324	                   q, in_queue);
325	    }
326	
327	    for (const auto &[buffer, layout] : layout_map) {
328	      strict_layout_map.Set(buffer, layout);
329	    }
330	
331	    // step 2: infer common layout with BFS
332	    FinishInferQueue(InferLevel::kCommon, layout_map, strict_layout_map, q,
333	                     in_queue);
334	    // step 3: relax constraints to free and re-run
335	    InferInFreeMode(layout_map, strict_layout_map);
336	    // step 4: finalize alias layouts by Var
337	    // For each storage var, if any buffer in the group has a layout,
338	    // propagate (reshape if needed) to the rest to ensure completeness.
339	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
340	      // Find a representative with existing layout
341	      Optional<Buffer> rep;
342	      Optional<Layout> rep_layout;
343	      for (const auto &buf : buffers) {
344	        if (layout_map.count(buf)) {
345	          rep = buf;
346	          rep_layout = layout_map[buf];
347	          break;
348	        }
349	      }
350	      if (!rep_layout.defined())
351	        continue;
352	      for (const auto &buf : buffers) {
353	        if (!layout_map.count(buf)) {
354	          bool shapes_equal =
355	              rep_layout.value()->InputShape().size() == buf->shape.size();
356	          if (shapes_equal) {
357	            for (size_t i = 0; i < rep_layout.value()->InputShape().size();
358	                 ++i) {
359	              if (!analyzer_.CanProveEqual(rep_layout.value()->InputShape()[i],
360	                                           buf->shape[i])) {
361	                shapes_equal = false;
362	                break;
363	              }
364	            }
365	          }
366	
367	          Layout reshaped = shapes_equal
368	                                ? rep_layout.value()
369	                                : rep_layout.value()->Reshape(
370	                                      buf->shape, &analyzer_,
371	                                      Integer(rep.value()->dtype.bytes()),
372	                                      Integer(buf->dtype.bytes()));
373	          layout_map.Set(buf, reshaped);
374	        }
375	      }
376	    }
377	
378	    // Check that all local.fragment buffers have inferred layouts
379	    for (const auto &[buffer, _] : use_list_) {
380	      if (IsFragmentBuffer(buffer)) {
381	        ICHECK_NE(layout_map.count(buffer), 0)
382	            << "The layout for fragment " << buffer
383	            << " can not be inferred correctly.";
384	      }
385	    }
386	
387	    // Collect layout info for For nodes
388	    Map<For, Fragment> for_map;
389	    Map<For, PrimExpr> predicate_map;
390	    ICHECK(infer_list_.size() == thread_var_vec_.size())
391	        << "infer_list_ and thread_var_vec_ size mismatch";
392	    for (int i = 0; i < infer_list_.size(); i++) {
393	      TileOperator base_infer = std::move(infer_list_[i]);
394	      auto thread_var = thread_var_vec_[i];
395	
396	      // Check if base_infer is valid
397	      ICHECK(base_infer.defined()) << "Null pointer encountered in "
398	                                      "infer_list_ while collecting for_map.";
399	      if (auto for_infer = base_infer.as<ParallelOpNode>()) {
400	        // Check that the loop layout is defined
401	        ICHECK(for_infer->GetLoopLayout().defined())
402	            << "The Layout for Parallel for cannot be inferred correctly:\n"
403	            << for_infer->GetRoot();
404	        for_map.Set(for_infer->GetRoot(), for_infer->GetLoopLayout());
405	        // thread_var_ should be defined if we rely on it
406	        ICHECK(thread_var.defined())
407	            << "thread_var is not defined. Cannot retrieve predicate.";
408	
409	        if (auto predicate = for_infer->GetPredicate(thread_var->var)) {
410	          predicate_map.Set(for_infer->GetRoot(), predicate.value());
411	        }
412	      }
413	    }
414	
415	    return {layout_map, for_map, predicate_map};
416	  }
417	
418	  void Collect(const PrimFunc &f) {
419	    for (const auto &[_, buffer] : f->buffer_map) {
420	      if (buffer_data_to_buffers_.count(buffer->data)) {
421	        auto buffers = buffer_data_to_buffers_[buffer->data];
422	        buffers.push_back(buffer);
423	        buffer_data_to_buffers_.Set(buffer->data, buffers);
424	      } else {
425	        buffer_data_to_buffers_.Set(buffer->data, {buffer});
426	      }
427	    }
428	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
429	    ICHECK(target.defined())
430	        << "Layout_Inference: Require the target attribute";
431	    target_ = target.value();
432	    this->operator()(f->body);
433	    // Compute floating fragment buffers after collection
434	    ComputeFloatingFragmentBuffers(f->body);
435	  }
