437	private:
438	  Map<Var, Buffer> GetBufferMap() const {
439	    Map<Var, Buffer> buffer_map;
440	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
441	      // Use the first buffer for each var
442	      // TODO(lei): phaseout buffer_map in future.
443	      if (!buffers.empty()) {
444	        buffer_map.Set(var, buffers[0]);
445	      }
446	    }
447	    return buffer_map;
448	  }
449	
450	  // Return true if any buffer that this op (idx) touches already has
451	  // an inferred layout in layout_map. Used to prioritize enqueue order.
452	  bool HasKnownLayoutAnchor(int idx, const LayoutMap &layout_map) const {
453	    auto it = op_touched_buffers_.find(idx);
454	    if (it == op_touched_buffers_.end() || it->second.empty())
455	      return false;
456	    for (const auto &buf : it->second) {
457	      if (layout_map.count(buf))
458	        return true;
459	    }
460	    return false;
461	  }
462	
463	  // Enqueue idx to q with priority if all its buffers already
464	  // have layouts. Also guards against duplicates and self-enqueue.
465	  void EnqueueWithPriority(int idx, std::deque<int> &q,
466	                           std::vector<bool> &in_queue, int cur_infer_id,
467	                           const LayoutMap &layout_map) const {
468	    if (idx == cur_infer_id)
469	      return;
470	    if (idx < 0 || idx >= static_cast<int>(in_queue.size()))
471	      return;
472	    if (in_queue[idx])
473	      return;
474	    in_queue[idx] = true;
475	    if (HasKnownLayoutAnchor(idx, layout_map)) {
476	      q.push_front(idx);
477	    } else {
478	      q.push_back(idx);
479	    }
480	  }
481	
482	  void VisitExpr_(const CallNode *op) final {
483	    IRVisitorWithAnalyzer::VisitExpr_(op);
484	    // Do not analysis the call node to the global function.
485	    if (op->op.as<GlobalVarNode>())
486	      return;
487	
488	    auto p = ParseOperator(tvm::ffi::GetRef<Call>(op));
489	    if (p.defined()) {
490	      for (const auto &arg : op->args) {
491	        if (auto buffer = getBufferFromAccessPtr(arg)) {
492	          addToUseList(buffer.value());
493	        } else if (auto buffer = getBufferFromRegion(arg)) {
494	          addToUseList(buffer.value());
495	        }
496	        // Check if the argument uses any LetStmt variables that reference
497	        // fragment buffers. If so, add those buffers to the use list.
498	        // This handles cases like: a = block_mask_f[i]; T.copy(A[a, 0], ...)
499	        CollectFragmentBuffersFromExpr(arg);
500	      }
501	      // Compute thread_var_ and thread_bounds_
502	      thread_var_vec_.push_back(thread_var_);
503	      if (analyzer_.const_int_bound.IsBound(thread_var_->var)) {
504	        auto const_int_bound = analyzer_.const_int_bound(thread_var_);
505	        auto min_value = const_int_bound->min_value;
506	        auto max_value = const_int_bound->max_value;
507	        auto extent = max_value - min_value + 1;
508	        auto dtype = thread_var_->var.dtype();
509	        thread_bounds_vec_.push_back(Range::FromMinExtent(
510	            IntImm(dtype, min_value), IntImm(dtype, extent)));
511	      } else {
512	        thread_bounds_vec_.push_back(Range::FromMinExtent(0, 1));
513	      }
514	      analyzer_vec_.push_back(analyzer_.Clone());
515	
516	      // Compute buffer oob for each buffer in the op
517	      if (const auto *copy = p.as<CopyNode>()) {
518	        auto src_tensor = copy->src;
519	        auto dst_tensor = copy->dst;
520	        auto src_range = copy->src_range;
521	        auto dst_range = copy->dst_range;
522	        bool src_oob = false;
523	        bool dst_oob = false;
524	        for (size_t i = 0; i < src_range.size(); i++) {
525	          if (!analyzer_.CanProve(src_range[i]->min + src_range[i]->extent <=
526	                                      src_tensor->shape[i],
527	                                  arith::ProofStrength::kSymbolicBound)) {
528	            src_oob = true;
529	            break;
530	          }
531	        }
532	        for (size_t i = 0; i < dst_range.size(); i++) {
533	          if (!analyzer_.CanProve(dst_range[i]->min + dst_range[i]->extent <=
534	                                      dst_tensor->shape[i],
535	                                  arith::ProofStrength::kSymbolicBound)) {
536	            dst_oob = true;
537	            break;
538	          }
539	        }
540	        buffer_oob_vec_.push_back(src_oob || dst_oob);
541	      } else {
542	        buffer_oob_vec_.push_back(false);
543	      }
544	
545	      // Add the tile operator to infer_list_
546	      infer_list_stmt_.push_back(tvm::ffi::GetRef<ObjectRef>(op));
547	      infer_list_.push_back(std::move(p));
548	    }
549	  }
550	
551	  Optional<Buffer> getBufferFromAccessPtr(const PrimExpr &expr) {
552	    if (auto bl = expr.as<BufferLoadNode>()) {
553	      return bl->buffer;
554	    }
555	    auto call = expr.as<CallNode>();
556	    if (!call) {
557	      return std::nullopt;
558	    }
559	    if (call->op.same_as(builtin::tvm_access_ptr())) {
560	      auto var_opt = call->args[1].as<Var>();
561	      if (!var_opt.has_value()) {
562	        LOG(WARNING) << "[getBufferFromAccessPtr] args[1] is not a Var, type: "
563	                     << call->args[1]->GetTypeKey();
564	        return std::nullopt;
565	      }
566	      const auto &var = var_opt.value();
567	      if (buffer_data_to_buffers_.count(var)) {
568	        const auto &buffers = buffer_data_to_buffers_[var];
569	        if (!buffers.empty()) {
570	          return buffers[0]; // Return the first buffer
571	        }
572	      }
573	      return std::nullopt;
574	    }
575	    return std::nullopt;
576	  }
577	
578	  Optional<Buffer> getBufferFromRegion(const PrimExpr &expr) {
579	    if (auto call = expr.as<CallNode>()) {
580	      if (call->op.same_as(RegionOp::Get())) {
581	        if (auto bl = call->args[0].as<BufferLoadNode>()) {
582	          return bl->buffer;
583	        }
584	        return std::nullopt;
585	      }
586	    }
587	    return std::nullopt;
588	  }
589	
590	  void addToUseList(const Buffer &buffer) {
591	    // buffer scope must be local.fragment
592	    if (!IsFragmentBuffer(buffer)) {
593	      return;
594	    }
595	    int infer_idx = infer_list_.size();
596	    if (use_list_.find(buffer) == use_list_.end()) {
597	      use_list_[buffer] = {};
598	    }
599	    use_list_[buffer].push_back(infer_idx);
600	
601	    // Track which buffers this op (infer_idx) touches for prioritization.
602	    // Avoid duplicates.
603	    auto &vec = op_touched_buffers_[infer_idx];
604	    if (std::none_of(vec.begin(), vec.end(),
605	                     [&](const Buffer &b) { return b.same_as(buffer); })) {
606	      vec.push_back(buffer);
607	    }
608	  }
609	
610	  void VisitStmt_(const ForNode *op) final {
611	    if (op->kind == ForKind::kParallel) {
612	      auto infer = ParallelOp(tvm::ffi::GetRef<For>(op));
613	      for (const auto &[buffer, _] : infer->GetIndiceMap()) {
614	        addToUseList(buffer);
615	      }
616	
617	      PostOrderVisit(op->body, [this](const ObjectRef &node) {
618	        if (auto *buffer_load = node.as<BufferLoadNode>()) {
619	          if (buffer_load->buffer.defined() &&
620	              buffer_load->buffer->data.defined()) {
621	            if (buffer_data_to_buffers_.count(buffer_load->buffer->data)) {
622	              // Check if this buffer is already in the list
623	              auto buffers = buffer_data_to_buffers_[buffer_load->buffer->data];
624	              bool found = false;
625	              for (const auto &buf : buffers) {
626	                if (buf.same_as(buffer_load->buffer)) {
627	                  found = true;
628	                  break;
629	                }
630	              }
631	              if (!found) {
632	                buffers.push_back(buffer_load->buffer);
633	                buffer_data_to_buffers_.Set(buffer_load->buffer->data, buffers);
634	                DLOG(INFO) << "[LayoutInference] BufferStore: added buffer "
635	                           << buffer_load->buffer
636	                           << " buffer.get() = " << buffer_load->buffer.get()
637	                           << " data = " << buffer_load->buffer->data.get();
638	              }
639	            } else {
640	              buffer_data_to_buffers_.Set(buffer_load->buffer->data,
641	                                          {buffer_load->buffer});
642	              DLOG(INFO) << "[LayoutInference] BufferStore: new buffer "
643	                         << buffer_load->buffer
644	                         << " buffer.get() = " << buffer_load->buffer.get()
645	                         << " data = " << buffer_load->buffer->data.get();
646	            }
647	          }
648	        } else if (auto *buffer_store = node.as<BufferStoreNode>()) {
649	          if (buffer_store->buffer.defined() &&
650	              buffer_store->buffer->data.defined()) {
651	            if (buffer_data_to_buffers_.count(buffer_store->buffer->data)) {
652	              auto buffers =
653	                  buffer_data_to_buffers_[buffer_store->buffer->data];
654	              bool found = false;
655	              for (const auto &buf : buffers) {
656	                if (buf.same_as(buffer_store->buffer)) {
657	                  found = true;
658	                  break;
659	                }
660	              }
661	              if (!found) {
662	                buffers.push_back(buffer_store->buffer);
663	                buffer_data_to_buffers_.Set(buffer_store->buffer->data,
664	                                            buffers);
665	                DLOG(INFO) << "[LayoutInference] BufferStore: added buffer "
666	                           << buffer_store->buffer
667	                           << " buffer.get() = " << buffer_store->buffer.get()
668	                           << " data = " << buffer_store->buffer->data.get();
669	              }
670	            } else {
671	              buffer_data_to_buffers_.Set(buffer_store->buffer->data,
672	                                          {buffer_store->buffer});
673	              DLOG(INFO) << "[LayoutInference] BufferStore: new buffer "
674	                         << buffer_store->buffer
675	                         << " buffer.get() = " << buffer_store->buffer.get()
676	                         << " data = " << buffer_store->buffer->data.get();
677	            }
678	          }
679	        }
680	      });
681	      infer_list_stmt_.push_back(tvm::ffi::GetRef<ObjectRef>(op));
682	      infer_list_.push_back(std::move(infer));
683	      thread_var_vec_.push_back(thread_var_);
684	      if (thread_var_.defined() &&
685	          analyzer_.const_int_bound.IsBound(thread_var_->var)) {
686	        auto const_int_bound = analyzer_.const_int_bound(thread_var_);
687	        auto dtype = thread_var_->var.dtype();
688	        auto extent =
689	            const_int_bound->max_value - const_int_bound->min_value + 1;
690	        thread_bounds_vec_.push_back(Range::FromMinExtent(
691	            IntImm(dtype, const_int_bound->min_value), IntImm(dtype, extent)));
692	      } else {
693	        thread_bounds_vec_.push_back(Range::FromMinExtent(0, 1));
694	      }
695	      analyzer_vec_.push_back(analyzer_.Clone());
696	      buffer_oob_vec_.push_back(false);
697	    } else {
698	      IRVisitorWithAnalyzer::VisitStmt(op->body);
699	    }
700	  }
701	
702	  void VisitStmt_(const BlockNode *op) final {
703	    for (auto buffer : op->alloc_buffers) {
704	      if (buffer_data_to_buffers_.count(buffer->data)) {
705	        auto buffers = buffer_data_to_buffers_[buffer->data];
706	        buffers.push_back(buffer);
707	        buffer_data_to_buffers_.Set(buffer->data, buffers);
708	      } else {
709	        buffer_data_to_buffers_.Set(buffer->data, {buffer});
710	      }
711	    }
712	
713	    // First, visit the block body to collect all buffers from
714	    // BufferLoad/BufferStore
715	    IRVisitorWithAnalyzer::VisitStmt_(op);
716	
717	    // After visiting, apply layouts to all collected buffers
718	    if (op->annotations.count(attr::kLayoutMap)) {
719	      // Check if the layout map is Map<Var, Layout>
720	      auto map =
721	          op->annotations.Get(attr::kLayoutMap)->as<Map<Var, Layout>>().value();
722	      for (const auto &[var, layout] : map) {
723	        ICHECK(buffer_data_to_buffers_.count(var))
724	            << "buffer " << var << " is not found in the block";
725	        const auto &buffers = buffer_data_to_buffers_[var];
726	        ICHECK(!buffers.empty()) << "buffer list for " << var << " is empty";
727	        // Apply layout to all buffers associated with this var
728	        for (const auto &buffer : buffers) {
729	
730	          // Reshape the layout to match the buffer's shape
731	          // Check if shapes are structurally equal
732	          bool shapes_equal =
733	              layout->InputShape().size() == buffer->shape.size();
734	          if (shapes_equal) {
735	            for (size_t i = 0; i < layout->InputShape().size(); ++i) {
736	              if (!analyzer_.CanProveEqual(layout->InputShape()[i],
737	                                           buffer->shape[i])) {
738	                shapes_equal = false;
739	                break;
740	              }
741	            }
742	          }
743	
744	          if (shapes_equal) {
745	            annotated_layout_map_.Set(buffer, layout);
746	          } else {
747	            // Use the first buffer sharing this var as the base for dtype ratio
748	            int base_bytes = buffers[0]->dtype.bytes();
749	            auto reshaped_layout =
750	                layout->Reshape(buffer->shape, &analyzer_, Integer(base_bytes),
751	                                Integer(buffer->dtype.bytes()));
752	            annotated_layout_map_.Set(buffer, reshaped_layout);
753	          }
754	        }
755	      }
756	    }
757	  }
758	
759	  void VisitStmt_(const AttrStmtNode *op) final {
760	    if (op->attr_key == tir::attr::thread_extent) {
761	      IterVar iv = Downcast<IterVar>(op->node);
762	      if (iv->thread_tag == "threadIdx.x") {
763	        ICHECK(iv->dom->extent.as<IntImmNode>());
764	        thread_var_ = iv;
765	      }
766	    }
767	    IRVisitorWithAnalyzer::VisitStmt_(op);
768	  }
769	
770	  void VisitStmt_(const LetStmtNode *op) final {
771	    // Record Let variable to its bound expression.
772	    // This enables tracking fragment buffer accesses through let bindings.
773	    let_var_to_expr_.Set(op->var, op->value);
774	    IRVisitorWithAnalyzer::VisitStmt_(op);
775	  }
776	
777	  // Helper: recursively collect fragment buffers from an expression,
778	  // following let bindings chain.
779	  void CollectFragmentBuffersFromExpr(const PrimExpr &expr) {
780	    PostOrderVisit(expr, [this](const ObjectRef &node) {
781	      if (auto bl = node.as<BufferLoadNode>()) {
782	        if (IsFragmentBuffer(bl->buffer)) {
783	          addToUseList(bl->buffer);
784	        }
785	      } else if (auto var_node = node.as<VarNode>()) {
786	        auto var = tvm::ffi::GetRef<Var>(var_node);
787	        if (let_var_to_expr_.count(var)) {
788	          CollectFragmentBuffersFromExpr(let_var_to_expr_[var]);
789	        }
790	      }
791	    });
792	  }
793	
794	  void VisitExpr_(const BufferLoadNode *op) final {
795	    // Collect buffer from BufferLoad
796	    if (op->buffer.defined() && op->buffer->data.defined()) {
797	      if (buffer_data_to_buffers_.count(op->buffer->data)) {
798	        // Check if this buffer is already in the list
799	        auto buffers = buffer_data_to_buffers_[op->buffer->data];
800	        bool found = false;
801	        for (const auto &buf : buffers) {
802	          if (buf.same_as(op->buffer)) {
803	            found = true;
804	            break;
805	          }
806	        }
807	        if (!found) {
808	          buffers.push_back(op->buffer);
809	          buffer_data_to_buffers_.Set(op->buffer->data, buffers);
810	          DLOG(INFO) << "[LayoutInference] BufferLoad: added buffer "
811	                     << op->buffer << " buffer.get() = " << op->buffer.get()
812	                     << " data = " << op->buffer->data.get();
813	        }
814	      } else {
815	        buffer_data_to_buffers_.Set(op->buffer->data, {op->buffer});
816	        DLOG(INFO) << "[LayoutInference] BufferLoad: new buffer " << op->buffer
817	                   << " buffer.get() = " << op->buffer.get()
818	                   << " data = " << op->buffer->data.get();
819	      }
820	    }
821	    IRVisitorWithAnalyzer::VisitExpr_(op);
822	  }
823	
824	  void VisitStmt_(const BufferStoreNode *op) final {
825	    // Collect buffer from BufferStore
826	    if (op->buffer.defined() && op->buffer->data.defined()) {
827	      if (buffer_data_to_buffers_.count(op->buffer->data)) {
828	        // Check if this buffer is already in the list
829	        auto buffers = buffer_data_to_buffers_[op->buffer->data];
830	        bool found = false;
831	        for (const auto &buf : buffers) {
832	          if (buf.same_as(op->buffer)) {
833	            found = true;
834	            break;
835	          }
836	        }
837	        if (!found) {
838	          buffers.push_back(op->buffer);
839	          buffer_data_to_buffers_.Set(op->buffer->data, buffers);
840	          DLOG(INFO) << "[LayoutInference] BufferStore: added buffer "
