853	
854	  // Compute floating fragment buffers after collection is done.
855	  //
856	  // A "floating" fragment buffer is one that has accesses outside of any
857	  // TileOp (Copy, Gemm, Reduce, Parallel, etc.). For example:
858	  //
859	  //   T.copy(BlockMask[by, :], block_mask_f)  // block_mask_f accessed IN
860	  //   TileOp for i in T.Pipelined(N_S):
861	  //       if block_mask_f[i] >= 0:           // block_mask_f accessed OUTSIDE
862	  //       TileOp (floating!)
863	  //           T.copy(A[...], A_shared)
864	  //
865	  // In this example, `block_mask_f[i]` in the if-condition is a "floating"
866	  // access because it's not inside any TileOp. Such buffers need special
867	  // handling: they must be fully replicated across all threads since the
868	  // access pattern cannot be inferred from TileOp semantics.
869	  //
870	  // This function identifies these buffers by:
871	  // 1. Collecting all IR nodes that are inside TileOps (from infer_list_stmt_)
872	  // 2. Scanning the entire function body for fragment buffer accesses
873	  // 3. Any access not inside a TileOp means the buffer is "floating"
874	  // 4. Recording the thread_bounds at the point of each floating access
875	  void ComputeFloatingFragmentBuffers(const Stmt &func_body) {
876	    // Step 1: Collect all nodes that are inside TileOps
877	    std::unordered_set<const Object *> nodes_in_tileops;
878	    for (const auto &stmt : infer_list_stmt_) {
879	      PostOrderVisit(stmt, [&](const ObjectRef &node) {
880	        nodes_in_tileops.insert(node.get());
881	      });
882	    }
883	
884	    // Step 2: Use a visitor to scan for floating accesses while tracking thread
885	    // context
886	    class FloatingBufferCollector : public IRVisitorWithAnalyzer {
887	    public:
888	      FloatingBufferCollector(
889	          const std::unordered_set<const Object *> &nodes_in_tileops,
890	          std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
891	              &floating_buffers)
892	          : nodes_in_tileops_(nodes_in_tileops),
893	            floating_buffers_(floating_buffers) {}
894	
895	      void VisitStmt_(const AttrStmtNode *op) final {
896	        if (op->attr_key == tir::attr::thread_extent) {
897	          IterVar iv = Downcast<IterVar>(op->node);
898	          if (iv->thread_tag == "threadIdx.x") {
899	            thread_var_ = iv;
900	          }
901	        }
902	        IRVisitorWithAnalyzer::VisitStmt_(op);
903	      }
904	
905	      void VisitExpr_(const BufferLoadNode *op) final {
906	        CheckFloatingAccess(op->buffer, op);
907	        IRVisitorWithAnalyzer::VisitExpr_(op);
908	      }
909	
910	      void VisitStmt_(const BufferStoreNode *op) final {
911	        CheckFloatingAccess(op->buffer, op);
912	        IRVisitorWithAnalyzer::VisitStmt_(op);
913	      }
914	
915	    private:
916	      void CheckFloatingAccess(const Buffer &buffer, const Object *node) {
917	        if (!IsFragmentBuffer(buffer))
918	          return;
919	        if (nodes_in_tileops_.find(node) != nodes_in_tileops_.end())
920	          return;
921	        // This is a floating access - record buffer with current thread_bounds
922	        if (floating_buffers_.find(buffer) != floating_buffers_.end())
923	          return; // Already recorded
924	        Range thread_bounds = Range::FromMinExtent(0, 1);
925	        if (thread_var_.defined() &&
926	            analyzer_.const_int_bound.IsBound(thread_var_->var)) {
927	          auto const_int_bound = analyzer_.const_int_bound(thread_var_);
928	          auto dtype = thread_var_->var.dtype();
929	          auto extent =
930	              const_int_bound->max_value - const_int_bound->min_value + 1;
931	          thread_bounds = Range::FromMinExtent(
932	              IntImm(dtype, const_int_bound->min_value), IntImm(dtype, extent));
933	        }
934	        floating_buffers_[buffer] = thread_bounds;
935	      }
936	
937	      const std::unordered_set<const Object *> &nodes_in_tileops_;
938	      std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
939	          &floating_buffers_;
940	      IterVar thread_var_;
941	    };
942	
943	    FloatingBufferCollector collector(nodes_in_tileops,
944	                                      floating_fragment_buffers_);
945	    collector(func_body);
946	
947	    // Debug log floating fragment buffers
948	    if (!floating_fragment_buffers_.empty()) {
949	      DLOG(INFO)
950	          << "Floating fragment buffers (have accesses outside TileOps):";
951	      for (const auto &[buffer, thread_bounds] : floating_fragment_buffers_) {
952	        DLOG(INFO) << "    " << buffer
953	                   << " with thread_bounds: " << thread_bounds;
954	      }
955	    }
956	  }
957	
958	  Map<Var, Array<Buffer>> buffer_data_to_buffers_;
959	  // Map from LetStmt variable to its bound expression
960	  Map<Var, PrimExpr> let_var_to_expr_;
961	  std::vector<ObjectRef> infer_list_stmt_;
962	  std::vector<TileOperator> infer_list_;
963	  // Fragment buffers that have accesses outside of TileOps.
964	  // These "floating" buffers need fully replicated layouts since their
965	  // access patterns cannot be inferred from TileOp semantics.
966	  // Maps buffer -> thread_bounds at the point of floating access.
967	  // See ComputeFloatingFragmentBuffers() for detailed explanation.
968	  std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
969	      floating_fragment_buffers_;
970	  std::unordered_map<Buffer, std::vector<int>, ObjectPtrHash, ObjectPtrEqual>
971	      use_list_;
972	  // Per-op list of buffers it touches (fragment scope), used for prioritization
973	  std::unordered_map<int, std::vector<Buffer>> op_touched_buffers_;
974	  // This is a workaround for cpu backend,
975	  // we need to define a thread_var for the serial loop.
976	  IterVar thread_var_ = IterVar(Range::FromMinExtent(0, 1), Var("v_thread"),
977	                                IterVarType::kDataPar);
978	  std::vector<IterVar> thread_var_vec_;
979	  std::vector<Range> thread_bounds_vec_;
980	  std::vector<std::unique_ptr<arith::Analyzer>> analyzer_vec_;
981	  std::vector<bool> buffer_oob_vec_;
982	  Target target_;
983	  LayoutMap annotated_layout_map_;
984	  bool skip_thread_partition_{false};
985	
986	  std::vector<TileOperator> BackupInferList() {
987	    std::vector<TileOperator> back_infer_list;
988	    back_infer_list.reserve(infer_list_.size());
989	    for (auto &&p : infer_list_) {
990	      back_infer_list.push_back(p->Clone());
991	    }
992	    return back_infer_list;
993	  }
994	
995	  void InferInFreeMode(LayoutMap &layout_map,
996	                       const LayoutMap &strict_layout_map) {
997	
998	    DLOG(INFO) << "Enforced layout maps:" << '\n';
999	    for (auto &&[k, v] : layout_map) {
1000	      DLOG(INFO) << "    " << k << ": " << v->DebugOutput() << '\n';
1001	    }
1002	    DLOG(INFO) << '\n';
1003	
1004	    // Group operators into connected components
1005	    UnionFind<int> uf;
1006	    for (int i = 0; i < infer_list_.size(); i++) {
1007	      uf.MakeSet(i);
1008	    }
1009	    for (const auto &[buffer, infer_indices] : use_list_) {
1010	      if (infer_indices.empty())
1011	        continue;
1012	
1013	      // Union all infer_list_ indices that share the same Buffer object
1014	      int first_idx = infer_indices[0];
1015	      for (size_t i = 1; i < infer_indices.size(); i++) {
1016	        uf.Union(first_idx, infer_indices[i]);
1017	      }
1018	    }
1019	    // Additionally, union across buffers that share the same underlying
1020	    // buffer->data (Var). This handles cases like reshape where multiple
1021	    // Buffer objects alias the same storage.
1022	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
1023	      std::vector<int> merged;
1024	      for (const auto &buf : buffers) {
1025	        auto it = use_list_.find(buf);
1026	        if (it != use_list_.end()) {
1027	          const auto &vec = it->second;
1028	          merged.insert(merged.end(), vec.begin(), vec.end());
1029	        }
1030	      }
1031	      if (merged.size() > 1) {
1032	        std::sort(merged.begin(), merged.end());
1033	        merged.erase(std::unique(merged.begin(), merged.end()), merged.end());
1034	        int first = merged[0];
1035	        for (size_t i = 1; i < merged.size(); ++i) {
1036	          uf.Union(first, merged[i]);
1037	        }
1038	      }
1039	    }
1040	
1041	    std::unordered_map<int, std::vector<int>> components;
1042	    for (int i = 0; i < infer_list_.size(); i++) {
1043	      int root = uf.Find(i);
1044	      components[root].push_back(i);
1045	    }
1046	    // Create a map from root to buffers
1047	    std::unordered_map<int, std::vector<Buffer>> components_buffers;
1048	    for (const auto &[buffer, infer_indices] : use_list_) {
1049	      int root = uf.Find(infer_indices[0]);
1050	      components_buffers[root].push_back(buffer);
1051	    }
1052	    // Keep components_buffers for debug purpose
1053	    (void)components_buffers;
1054	
1055	    // For each component, try each op as root, and determine the least
1056	    // replicated one
1057	    std::deque<int> q;
1058	    std::vector<bool> in_queue(infer_list_.size(), false);
1059	
1060	    for (auto &&[root, members] : components) {
1061	      DLOG(INFO) << "======================= processing component " << root
1062	                 << '\n';
1063	      decltype(infer_list_) best_infer_list;
1064	      LayoutMap best_layout_map;
1065	      int64_t min_reg_num = INT64_MAX;
1066	      int min_reg_num_infer_root = -1;
1067	
1068	      // Try each member as the root of inference for this component
1069	      for (int attempt_infer_root : members) {
1070	        DLOG(INFO) << "----------------------- try root " << attempt_infer_root
1071	                   << " members " << members.size() << '\n';
1072	        // Backup the current infer_list_ state
1073	        auto back_infer_list = BackupInferList();
1074	        // Copy the current layout_map for temporary use
1075	        LayoutMap tmp_layout_map = layout_map;
1076	        bool do_update = true;
1077	        try {
1078	          // Run inference starting from attempt_infer_root
1079	          RunInferStep(attempt_infer_root, InferLevel::kFree, true,
1080	                       tmp_layout_map, strict_layout_map, q, in_queue);
1081	          FinishInferQueue(InferLevel::kFree, tmp_layout_map, strict_layout_map,
1082	                           q, in_queue);
1083	
1084	          // After the first search, run inference for all other members in
1085	          // order
1086	          for (int other_infer_root : members) {
1087	            if (other_infer_root != attempt_infer_root) {
1088	              RunInferStep(other_infer_root, InferLevel::kFree, true,
1089	                           tmp_layout_map, strict_layout_map, q, in_queue);
1090	              FinishInferQueue(InferLevel::kFree, tmp_layout_map,
1091	                               strict_layout_map, q, in_queue);
1092	            }
1093	          }
1094	        } catch (const LayoutConflictException &e) {
1095	          do_update = false;
1096	          DLOG(INFO) << "attempt failed due to LayoutConflictException "
1097	                     << e.what() << '\n';
1098	        } catch (const NormalizeIterException &e) {
1099	          do_update = false;
1100	          DLOG(INFO) << "attempt failed due to NormalizeIterException "
1101	                     << e.what() << '\n';
1102	        } catch (const LoopLayoutInjectiveException &e) {
1103	          do_update = false;
1104	          DLOG(INFO) << "attempt failed due to LoopLayoutInjectiveException "
1105	                     << e.what() << '\n';
1106	        }
1107	
1108	        if (do_update) {
1109	          // Compute the total register number for this layout
1110	          int64_t reg_num = 0;
1111	          for (const auto &[buffer, layout] : tmp_layout_map) {
1112	            if (auto frag = layout.as<Fragment>()) {
1113	              int64_t frag_reg_num = 1;
1114	              for (auto i : frag.value()->OutputShape()) {
1115	                auto pci = as_const_int(i);
1116	                ICHECK(pci != nullptr)
1117	                    << "Can not use non-constant range to "
1118	                       "iterate over a fragment/local "
1119	                       "buffer. Non-constant shape expr is: "
1120	                    << i
1121	                    << ". This is possibly because you use symbolic shape when "
1122	                       "accessing a fragment/local buffer.";
1123	                frag_reg_num *= *pci;
1124	              }
1125	              reg_num += frag_reg_num;
1126	            }
1127	          }
1128	          // Update the best plan if this one uses fewer registers
1129	          if (reg_num < min_reg_num ||
1130	              (reg_num == min_reg_num &&
1131	               attempt_infer_root < min_reg_num_infer_root)) {
1132	            best_infer_list =
1133	                BackupInferList(); // Use backup to avoid moving out infer_list_
1134	            best_layout_map = tmp_layout_map;
1135	            min_reg_num = reg_num;
1136	            min_reg_num_infer_root = attempt_infer_root;
1137	          }
1138	        }
1139	        // Restore infer_list_ state for the next attempt
1140	        infer_list_ = std::move(back_infer_list);
1141	      }
1142	      ICHECK(min_reg_num < INT64_MAX) << "no available layout found" << '\n';
1143	      // Apply the best plan for this component
1144	      infer_list_ = std::move(best_infer_list);
1145	      layout_map = best_layout_map;
1146	      DLOG(INFO) << "[InferInFreeMode] Final selection is attempt_infer_root = "
1147	                 << min_reg_num_infer_root << '\n';
1148	    }
1149	  }
1150	};
1151	
1152	class LayoutInferencer : public IRMutatorWithAnalyzer {
1153	public:
1154	  static PrimFunc Substitute(PrimFunc f, bool skip_thread_partition = false) {
1155	    arith::Analyzer analyzer;
1156	    PrimFuncNode *fptr = f.CopyOnWrite();
1157	    fptr->body = ParallelLoopFuser::Fuse(f->body);
1158	    BufferUseDefCollector collector(skip_thread_partition);
1159	    collector.Collect(f);
1160	    auto result = collector.Run();
1161	    LayoutInferencer substituter(result, &analyzer);
1162	    fptr->body = substituter.VisitStmt(f->body);
1163	    return f;
1164	  }
1165	
1166	private:
1167	  LayoutInferencer(const LayoutInferenceResult &result,
1168	                   arith::Analyzer *analyzer)
1169	      : arith::IRMutatorWithAnalyzer(analyzer), result_(result) {};
1170	
1171	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
1172	
1173	  /**
1174	   * @brief Visit and mutate a Block node to attach inferred layout information.
1175	   *
1176	   * Converts the visited Block via the base visitor, asserts that every buffer
1177	   * allocated with scope "local.framgent" has an inferred layout in
1178	   * result_.layout_map, and attaches result_.layout_map to the Block's
1179	   * annotations under attr::kLayoutMap.
1180	   *
1181	   * If any "local.framgent" buffer lacks an entry in result_.layout_map an
1182	   * ICHECK will fail with the offending buffer printed.
1183	   *
1184	   * @return Stmt The (possibly modified) Block statement with the layout-map
1185	   * annotation set.
1186	   */
1187	  Stmt VisitStmt_(const BlockNode *op) final {
1188	    Block block = Downcast<Block>(IRMutatorWithAnalyzer::VisitStmt_(op));
1189	
1190	    for (auto buffer : block->alloc_buffers) {
1191	      if (buffer.scope() == "local.framgent") {
1192	        ICHECK(result_.layout_map.count(buffer))
1193	            << "Cannot inference fragment layout for " << buffer;
1194	      }
1195	    }
1196	    auto block_ptr = block.CopyOnWrite();
1197	    block_ptr->annotations.Set(attr::kLayoutMap, result_.layout_map);
1198	    return block;
1199	  }
1200	
1201	  /**
1202	   * @brief Visit and transform For nodes by storing inferred layout information
1203	   *        as annotations instead of expanding the loop.
1204	   *
1205	   * If the For node is present in result_.for_map, this method stores the
1206	   * inferred loop layout and predicate as annotations on the For node, rather
1207	   * than performing loop partition and vectorization.
1208	   *
1209	   * The stored annotations are:
1210	   * - attr::kParallelLoopLayout: The Fragment layout for the parallel loop
1211	   * - attr::kParallelLoopPredicate: The predicate expression (if any)
1212	   *
1213	   * @return The For statement with layout annotations attached
1214	   */
1215	  Stmt VisitStmt_(const ForNode *op) final {
1216	    if (!result_.for_map.count(tvm::ffi::GetRef<For>(op))) {
1217	      return IRMutatorWithAnalyzer::VisitStmt_(op);
1218	    }
1219	
1220	    For for_node = Downcast<For>(IRMutatorWithAnalyzer::VisitStmt_(op));
1221	    auto root = tvm::ffi::GetRef<For>(op);
1222	
1223	    auto loop_layout = result_.for_map[root];
1224	
1225	    // Store the loop layout as an annotation on the For node
1226	    auto for_ptr = for_node.CopyOnWrite();
1227	    for_ptr->annotations.Set(attr::kParallelLoopLayout, loop_layout);
1228	
1229	    // Store the predicate as an annotation if it exists and is not trivially
1230	    // true
1231	    if (result_.predicate_map.count(root)) {
1232	      PrimExpr predicate = analyzer_->Simplify(result_.predicate_map[root]);
1233	      // Only store predicate if it's not trivially true
1234	      if (!is_const_int(predicate, 1)) {
1235	        for_ptr->annotations.Set(attr::kParallelLoopPredicate, predicate);
1236	      }
1237	    }
1238	
1239	    return for_node;
1240	  }
1241	
1242	  Stmt VisitStmt_(const AttrStmtNode *op) final {
1243	    if (op->attr_key == tir::attr::thread_extent) {
1244	      IterVar iv = Downcast<IterVar>(op->node);
1245	    }
1246	    return IRMutatorWithAnalyzer::VisitStmt_(op);
1247	  }
1248	
1249	private:
1250	  const LayoutInferenceResult result_;
1251	};
1252	
1253	tvm::transform::Pass LayoutInference() {
1254	  using namespace tir::transform;
1255	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
1256	    f.CopyOnWrite()->body = ParallelLoopTransformer::Substitute(f->body);
1257	    ThreadBindingCollector collector;
1258	    collector(f->body);
1259	    bool has_thread_binding = !collector.thread_binding_.empty();
1260	    bool skip_thread_partition = !has_thread_binding;
1261	    f = LayoutInferencer::Substitute(std::move(f), skip_thread_partition);
1262	    // Validate parallel loop layout annotations
1263	    ParallelLoopLayoutValidator::Validate(f->body);
1264	    return f;
1265	  };
1266	  return CreatePrimFuncPass(pass_func, 0, "tl.LayoutInference", {});
1267	}
1268	
1269	TVM_FFI_STATIC_INIT_BLOCK() {
1270	  namespace refl = tvm::ffi::reflection;
1271	  refl::GlobalDef().def("tl.transform.LayoutInference", LayoutInference);
1272	}
