55	    ICHECK(false) << "Unrecognized reducer_info rep: " << rep_str;
56	}
57	
58	class ReducerLayoutAnnotator : public IRMutatorWithAnalyzer {
59	public:
60	private:
61	  /**
62	   * @brief Visit an attribute statement and capture the IterVar for
63	   * threadIdx.x.
64	   *
65	   * If the attribute key is `tir::attr::thread_extent` and the node is an
66	   * `IterVar` whose `thread_tag` equals `"threadIdx.x"`, this sets the
67	   * mutator's `thread_var_` to that IterVar (after asserting the iterator's
68	   * extent is an `IntImm`). The previous `thread_var_` is preserved and
69	   * restored after delegating to the base visitor. Delegates all traversal work
70	   * to `IRMutatorWithAnalyzer::VisitStmt_`.
71	   *
72	   * Side effects:
73	   * - Temporarily updates the member `thread_var_` during traversal of the
74	   * child statement so subsequent visitors can read the thread index IterVar.
75	   *
76	   * @return The possibly mutated statement returned by the base visitor.
77	   */
78	  Stmt VisitStmt_(const AttrStmtNode *op) final {
79	    auto prev_thread_var = thread_var_;
80	    if (op->attr_key == tir::attr::thread_extent) {
81	      IterVar iv = Downcast<IterVar>(op->node);
82	      if (iv->thread_tag == "threadIdx.x") {
83	        ICHECK(iv->dom->extent.as<IntImmNode>());
84	        thread_var_ = iv;
85	      }
86	    }
87	    auto result = IRMutatorWithAnalyzer::VisitStmt_(op);
88	    thread_var_ = prev_thread_var;
89	    return result;
90	  }
91	
92	  /**
93	   * @brief Visits a TIR Block node to collect reducer metadata and apply
94	   * discovered buffer layouts.
95	   *
96	   * This method:
97	   * - Extracts reducer information from the block's `attr::kReducerInfo`
98	   * annotation and populates the internal reducer_info_map_.
99	   * - Registers allocated buffers by mapping each buffer's data Var to its
100	   * Buffer in var_to_buffer_.
101	   * - Recursively visits and rewrites the block body via the base mutator.
102	   * - Merges any layouts accumulated in new_layout_map_ into the block's
103	   * `attr::kLayoutMap` annotation (creating or extending the annotation), then
104	   * clears new_layout_map_ for subsequent blocks.
105	   *
106	   * Side effects:
107	   * - Updates reducer_info_map_, var_to_buffer_, and may set the block-level
108	   * `kLayoutMap` annotation.
109	   * - Clears new_layout_map_ after merging.
110	   *
111	   * @param op The Block node being visited.
112	   * @return Stmt The potentially modified Block statement (as a Stmt).
113	   */
114	  Stmt VisitStmt_(const BlockNode *op) final {
115	    // Record annotations
116	    if (op->annotations.count(attr::kReducerInfo)) {
117	      auto map = op->annotations.Get(attr::kReducerInfo)
118	                     ->as<Map<Var, Map<String, String>>>();
119	      ICHECK(map) << "reducer_replication map is not defined";
120	      for (auto &&[var, rep] : map.value()) {
121	        reducer_info_map_.Set(
122	            var, ReducerInfo{rep.Get("op").value(), rep.Get("rep").value()});
123	      }
124	    }
125	    for (auto &&buffer : op->alloc_buffers) {
126	      var_to_buffer_.Set(buffer->data, buffer);
127	    }
128	    auto result = IRMutatorWithAnalyzer::VisitStmt_(op).as<Block>().value();
129	    // After iterating over the body, set all layout_map to block
130	    auto p_result = result.CopyOnWrite();
131	    auto layout_map = p_result->annotations.Get(attr::kLayoutMap)
132	                          ->as<Map<Var, Layout>>()
133	                          .value_or(Map<Var, Layout>());
134	    for (auto &&[k, v] : new_layout_map_)
135	      layout_map.Set(k, v);
136	    if (!layout_map.empty())
137	      p_result->annotations.Set(attr::kLayoutMap, layout_map);
138	    new_layout_map_.clear();
139	    return result;
140	  }
141	
142	  /**
143	   * @brief Visit and possibly annotate a For node for reducer layout lowering.
144	   *
145	   * Visits a For node via the base mutator and, if the traversal is currently
146	   * inside a reduction region (tracked by inside_reducer_range_) and this is
147	   * the outermost loop of that region, annotates the loop with reducer
148	   * information and derives per-buffer layout fragments for each reducer
149	   * buffer.
150	   *
151	   * When annotating:
152	   * - Sets the block-level `attr::kReducerInfo` annotation to the current
153	   *   inside_reducer_range_ map on the loop.
154	   * - For each reducer buffer, reads the bound of `thread_var_` (requires the
155	   *   analyzer to have a const-int bound for it) and creates a Fragment:
156	   *   - If the reducer's replication type is ALL, creates a replication
157	   * fragment across the thread extent.
158	   *   - If the replication type is NONE, builds a flattened index expression
159	   *     across buffer indices, reduces it modulo the thread extent, adds the
160	   *     thread minimum offset, and uses that as the fragment index.
161	   * - Records the constructed Fragments into new_layout_map_ keyed by the
162	   *   buffer's data Var.
163	   *
164	   * Side effects:
165	   * - May set `attr::kReducerInfo` on the For node's annotations.
166	   * - Updates `new_layout_map_`.
167	   * - Reads and relies on `thread_var_`, `analyzer_->const_int_bound`, and
168	   *   `var_to_buffer_`.
169	   *
170	   * Preconditions and checks:
171	   * - `thread_var_` must be defined and have a constant-int bound when
172	   * annotating.
173	   * - Each reducer Var in inside_reducer_range_ must map to an allocated Buffer
174	   * in var_to_buffer_ (ICHECK enforced).
175	   *
176	   * @param op The original For node being visited.
177	   * @return The (possibly) transformed For statement.
178	   */
179	  Stmt VisitStmt_(const ForNode *op) final {
180	    // only annotate the outermost loop
181	    bool should_annotate = false;
182	    if (!inside_reducer_range_.empty() && !already_annotated_ &&
183	        op->kind == ForKind::kParallel) {
184	      should_annotate = true;
185	      already_annotated_ = true;
186	    }
187	
188	    auto opt_result = IRMutatorWithAnalyzer::VisitStmt_(op).as<For>();
189	    ICHECK(opt_result);
190	    auto result = opt_result.value();
191	
192	    if (should_annotate) {
193	      // we are leaving the current loop nest. later ones may annotate again
194	      already_annotated_ = false;
195	
196	      auto p_result = result.CopyOnWrite();
197	      p_result->annotations.Set(attr::kReducerInfo, inside_reducer_range_);
198	
199	      // Iterate over local.reducer.* buffers, append to reducer_op_map_, set
200	      // layout by adding layout_map annotations, and convert scope to
201	      // local.fragment
202	      for (auto &&[reducer_var, info] : inside_reducer_range_) {
203	        // analyze thread index bound, need to be inside WS section
204	        ICHECK(thread_var_.defined());
205	        ICHECK(analyzer_->const_int_bound.IsBound(thread_var_->var));
206	        auto const_int_bound = analyzer_->const_int_bound(thread_var_);
207	        int thread_min = const_int_bound->min_value;
208	        int thread_extent =
209	            const_int_bound->max_value - const_int_bound->min_value + 1;
210	
211	        auto opt_buffer = var_to_buffer_.Get(reducer_var);
212	        ICHECK(opt_buffer);
213	        const auto &buffer = opt_buffer.value();
214	        Fragment f;
215	        if (info->rep == ReducerRepType::ALL) {
216	          f = Fragment::FullyReplicated(buffer->shape, thread_extent);
217	        } else if (info->rep == ReducerRepType::NONE) {
218	          PrimExpr flatten_idx = InputPlaceholder(0);
219	          for (int i = 1; i < buffer->shape.size(); ++i)
220	            flatten_idx = flatten_idx * buffer->shape[i] + InputPlaceholder(i);
221	          f = Fragment(buffer->shape, {},
222	                       indexmod(flatten_idx, thread_extent) + thread_min, 1,
223	                       std::nullopt);
224	        }
225	        new_layout_map_.Set(buffer->data, f);
226	      }
227	    }
228	    return result;
229	  }
230	
231	  /**
232	   * @brief Handle BufferStore statements during IR mutation.
233	   *
234	   * This override is the visit hook for BufferStoreNode. Currently it delegates
235	   * to the base IRMutatorWithAnalyzer implementation. Intended as the place to
236	   * perform reducer-specific viability checks for stores (e.g., validating
237	   * operations against reducer metadata); such checks are TODO and are not yet
238	   * implemented.
239	   *
240	   * @return Stmt The (possibly transformed) statement returned by the base
241	   * mutator.
242	   */
243	  Stmt VisitStmt_(const BufferStoreNode *op) final {
244	    //! TODO: check store viable according to info->op
245	    return IRMutatorWithAnalyzer::VisitStmt_(op);
246	  }
247	
248	  /**
249	   * @brief Processes Call expressions to track reducer ranges and finalize
250	   * reducer operations.
251	   *
252	   * Visits call nodes, detects T.fill calls that target reducer buffers and
253	   * records their reducer metadata in inside_reducer_range_ until the matching
254	   * T.finalize_reducer is seen. When a FinalizeReducerOp call is encountered,
255	   * this method appends the reducer operation enum value to the call arguments
256	   * and removes the corresponding entry from inside_reducer_range_.
257	   *
258	   * Side effects:
259	   * - Inserts and removes entries in inside_reducer_range_.
260	   * - Mutates the FinalizeReducerOp call by pushing the reducer op enum as an
261	   * extra argument.
262	   *
263	   * Failure modes:
264	   * - ICHECK fails if a T.fill targets a reducer already recorded in
265	   * inside_reducer_range_ (i.e., a prior T.fill without an intervening
266	   * T.finalize_reducer).
267	   * - ICHECK fails if T.finalize_reducer has no matching T.fill (no entry in
268	   * inside_reducer_range_).
269	   *
270	   * @param op_ The CallNode being visited.
271	   * @return PrimExpr The (possibly modified) call expression.
272	   */
273	  PrimExpr VisitExpr_(const CallNode *op_) final {
274	    auto op_ref = IRMutatorWithAnalyzer::VisitExpr_(op_).as<Call>().value();
275	    auto op = op_ref.CopyOnWrite();
276	    if (op->op.same_as(Fill::Get())) {
277	      ICHECK(!op->args.empty());
278	      if (auto arg0_call = op->args[0].as<Call>()) {
279	        // tl.region(...) — extract buffer var from its first arg
280	        if (arg0_call.value()->op.same_as(RegionOp::Get())) {
281	          ICHECK(!arg0_call.value()->args.empty());
282	          if (auto bl = arg0_call.value()->args[0].as<BufferLoadNode>()) {
283	            Var var = bl->buffer->data;
284	            if (reducer_info_map_.count(var)) {
285	              ICHECK(inside_reducer_range_.count(var) == 0)
286	                  << "T.fill on reducer must be enclosed with a "
287	                     "T.finalize_reducer before next.";
288	              inside_reducer_range_.Set(var,
289	                                        reducer_info_map_.Get(var).value());
290	            }
291	          }
292	        }
293	        // builtin.tvm_access_ptr(...) — existing path (legacy)
294	        if (arg0_call.value()->op.same_as(builtin::tvm_access_ptr())) {
295	          ICHECK(arg0_call.value()->args.size() > 1);
296	          if (auto var = arg0_call.value()->args[1].as<Var>();
297	              var && reducer_info_map_.count(var.value())) {
298	            ICHECK(inside_reducer_range_.count(var.value()) == 0)
299	                << "T.fill on reducer must be enclosed with a "
300	                   "T.finalize_reducer "
301	                   "before next.";
302	            inside_reducer_range_.Set(
303	                var.value(), reducer_info_map_.Get(var.value()).value());
304	          }
305	        }
306	      } else if (auto bl = op->args[0].as<BufferLoadNode>()) {
307	        Var var = bl->buffer->data;
308	        if (reducer_info_map_.count(var)) {
309	          ICHECK(inside_reducer_range_.count(var) == 0)
310	              << "T.fill on reducer must be enclosed with a T.finalize_reducer "
311	                 "before next.";
312	          inside_reducer_range_.Set(var, reducer_info_map_.Get(var).value());
313	        }
314	      }
315	    } else if (op->op.same_as(FinalizeReducerOp::Get())) {
316	      ICHECK(op->args.size() == 1);
317	      Var var;
318	      if (auto bl = op->args[0].as<BufferLoadNode>()) {
319	        var = bl->buffer->data;
320	      } else if (auto reg_call = op->args[0].as<Call>()) {
321	        if (reg_call.value()->op.same_as(RegionOp::Get())) {
322	          if (auto bl2 = reg_call.value()->args[0].as<BufferLoadNode>()) {
323	            var = bl2->buffer->data;
324	          } else {
325	            LOG(FATAL) << "tl.region expects BufferLoad as first arg";
326	          }
327	        } else {
328	          var = GetVarFromAccessPtr(op->args[0]);
329	        }
330	      } else {
331	        var = GetVarFromAccessPtr(op->args[0]);
332	      }
333	      ICHECK(inside_reducer_range_.count(var) == 1)
334	          << "T.finalize_reducer must have a pairing T.fill ahead of it, "
335	             "enclosing a reduction range.";
336	      op->args.push_back((int)inside_reducer_range_.Get(var).value()->op);
337	      inside_reducer_range_.erase(var);
338	    }
339	    return op_ref;
340	  }
341	
342	  /**
343	   * @brief Construct a ReducerLayoutAnnotator with an arithmetic analyzer.
344	   *
345	   * Initializes the annotator's base IRMutatorWithAnalyzer with the provided
346	   * arith::Analyzer, which the mutator uses to query symbolic bounds and
347	   * simplify integer expressions during layout inference.
348	   *
349	   * @param analyzer Pointer to an arith::Analyzer used for symbolic analysis.
350	   */
351	  ReducerLayoutAnnotator(arith::Analyzer *analyzer)
352	      : IRMutatorWithAnalyzer(analyzer) {}
353	
354	  IterVar thread_var_;
355	  Map<Var, ReducerInfo> reducer_info_map_;
356	  Map<Var, ReducerInfo> inside_reducer_range_;
357	  bool already_annotated_ = false;
358	  Map<Var, Buffer> var_to_buffer_;
359	  Map<Var, Layout> new_layout_map_;
360	
361	public:
362	  /**
363	   * @brief Apply reducer layout substitution to a PrimFunc.
364	   *
365	   * Runs the ReducerLayoutAnnotator over the function body to collect reducer
366	   * metadata, insert layout mappings for reducer buffers, and lower
367	   * local.reducer usage to local.fragment-compatible forms. Returns a new
368	   * PrimFunc whose body is the transformed IR.
369	   *
370	   * @param f The PrimFunc to transform; passed by value and returned with an
371	   * updated body.
372	   * @return PrimFunc The transformed PrimFunc with reducer layouts and related
373	   * rewrites applied.
374	   */
375	  static PrimFunc Substitute(PrimFunc f) {
376	    arith::Analyzer analyzer;
377	    ReducerLayoutAnnotator substituter(&analyzer);
378	    PrimFuncNode *fptr = f.CopyOnWrite();
379	    fptr->body = substituter.VisitStmt(f->body);
380	    return f;
381	  }
382	};
383	
384	/**
385	 * @brief Create a TVM transform pass that lowers local.reducer buffers to
386	 * local.fragment layouts.
387	 *
388	 * This pass runs ReducerLayoutAnnotator::Substitute on a PrimFunc to collect
389	 * reducer metadata, compute per-buffer layout fragments for reducer buffers,
390	 * and annotate blocks with the resulting layout map. It is exposed as a
391	 * PrimFunc-level pass named "tl.LayoutReducer".
392	 *
393	 * @return tvm::transform::Pass A prim-function pass that applies the
394	 * layout-reduction substitution.
395	 */
396	tvm::transform::Pass LayoutReducer() {
397	  using namespace tir::transform;
398	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
399	    return ReducerLayoutAnnotator::Substitute(std::move(f));
400	  };
401	  return CreatePrimFuncPass(pass_func, 0, "tl.LayoutReducer", {});
402	}
403	
404	TVM_FFI_STATIC_INIT_BLOCK() {
405	  namespace refl = tvm::ffi::reflection;
406	  refl::GlobalDef().def("tl.transform.LayoutReducer", LayoutReducer);
407	}
408	
409	} // namespace tl
410	} // namespace tvm
